import{_ as a,a as t,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 31 Success story","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 31 Success story","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 30 Football or polo?","link":"/life/english/new-concept/book-2/unit-02/lesson-030"},"next":{"text":"第二册：实践与进步 · Lesson 32 Shopping made easy","link":"/life/english/new-concept/book-2/unit-02/lesson-032"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 30 Football or polo?","link":"/life/english/new-concept/book-2/unit-02/lesson-030"},"next":{"text":"第二册：实践与进步 · Lesson 32 Shopping made easy","link":"/life/english/new-concept/book-2/unit-02/lesson-032"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-031.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-031.md"}'),n={name:"life/english/new-concept/book-2/unit-02/lesson-031.md"};function i(r,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第二册-实践与进步-·-lesson-31-success-story" tabindex="-1">第二册：实践与进步 · Lesson 31 Success story <a class="header-anchor" href="#第二册-实践与进步-·-lesson-31-success-story" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 31 Success story&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>一家小修理铺逐渐成为稳定的生意，成功来自长时间积累；练习过去习惯与现在变化。本课的语言观察是：used to repair 表过去经常维修，如今情况已改变；be used to repairing 表已经习惯维修，不带同样的过去对照含义。完成学习后，请写一段小事业的发展，包含过去起点、现在规模和保留的习惯。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>business</td><td>/ˈbɪznəs/</td><td>n.</td><td>生意</td><td>start a business</td></tr><tr><td>factory</td><td>/ˈfæktəri/</td><td>n.</td><td>工厂</td><td>a small factory</td></tr><tr><td>save</td><td>/seɪv/</td><td>v.</td><td>节省；挽救</td><td>save money</td></tr><tr><td>success</td><td>/səkˈses/</td><td>n.</td><td>成功</td><td>achieve success</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>used to do — 过去常做，常暗示如今不同</li><li>save up — 积攒钱，用 for 引出目标</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：used to repair 表过去经常维修，如今情况已改变；be used to repairing 表已经习惯维修，不带同样的过去对照含义。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Mina used to repair bicycles in her parents&#39; garage.</p></blockquote><p>米娜过去常在父母的车库里修自行车。</p><p>used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 used to repair，used to 通常弱读；重读 Now 表示时间转折。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Mina used to repair bicycles in her parents&#39; garage. Now she runs a shop with three employees. She still repairs the oldest bicycles herself.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段小事业的发展，包含过去起点、现在规模和保留的习惯。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 repair/repairing：Mina used to ___ bicycles.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repair</p><p><strong>解析：</strong> used to 表过去习惯时接原形。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>现在店里有几名雇员？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Three.</p><p><strong>解析：</strong> 这里 three employees 指雇员数，不自动包含店主。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“她已习惯早起”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She is used to getting up early.</p><p><strong>解析：</strong> be used to 中 to 是介词，后接动名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-032">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
